import { Core } from "@m3l-automation/m3l-common";
import { configParameters } from "./config.js";
import { hooks } from "./hooks.js";
import { runFetch } from "./steps/run-fetch.js";
import { runUpsert } from "./steps/run-upsert.js";

const paths = new Core.M3LPaths();
const script = new Core.M3LScript({
  metadata: { name: "data-sync", version: "0.0.0" },
  config: { params: configParameters },
  hooks,
});

await Core.runScript(script, async () => {
  const config = await script.getConfiguration();
  // TODO: wire runFetch and runUpsert
  void runFetch;
  void runUpsert;
  void config;
  void paths;
});

import type { Core } from "@m3l-automation/m3l-common";

export async function runFetch(_deps: {
  readonly correlationId: string;
  readonly sourceTable: string;
  readonly batchLimit: number;
  readonly paths: Core.M3LPaths;
}): Promise<Record<string, unknown>[]> {
  throw new Error("not implemented");
}

